import{_ as a,o as r,a as e,b as d}from"./app.DKoEZOcr.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"guide/operator_practice/typical_operator_cases/simd_operator_impl/matmul_matrix_operator/getting_started.md","filePath":"guide/operator_practice/typical_operator_cases/simd_operator_impl/matmul_matrix_operator/getting_started.md","outlineHeaders":[{"level":2,"title":"详细内容","slug":"详细内容","link":"#详细内容"},{"level":3,"title":"可优化方向分析","slug":"可优化方向分析","link":"#可优化方向分析"}],"lastUpdated":1786954352000}'),o={name:"guide/operator_practice/typical_operator_cases/simd_operator_impl/matmul_matrix_operator/getting_started.md"};function i(s,t,n,l,p,_){return r(),e("div",null,[...t[0]||(t[0]=[d('<div><article class="markdown-body"><h1>入门功能落地<span id="ZH-CN_TOPIC_000000_ADD_ENTRY"></span></h1><p>本节使用基础API进行矩阵乘法的编程指导，介绍基于Ascend C编程模型和Cube计算单元实现矩阵算子的基本方法，算子中数据搬运和计算流水线通过事件同步进行协调，降低编程复杂度。</p><h2 id="详细内容">详细内容<a class="header-anchor" href="#详细内容">​</a></h2><p>详细内容请参考 <a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/00_introduction/02_matrix/matmul_basic_api">matmul样例</a>，该样例涵盖：</p><ul><li>算子实现：Global Tensor与Local Tensor的使用、DataCopy数据搬运、Matmul计算</li><li>功能调试：printf格式化输出、DumpTensor张量数据打印</li><li>编译运行：bisheng编译与执行</li><li>性能调试：msOpProf工具上板与仿真性能采集</li></ul><h3 id="可优化方向分析">可优化方向分析<a class="header-anchor" href="#可优化方向分析">​</a></h3><p>上述实现正确完成了矩阵乘功能，但在性能层面存在以下几类可优化的空间。</p><table><thead><tr><th>可优化方向</th><th>当前实现的问题</th><th>预期优化收益</th></tr></thead><tbody><tr><td><strong>L1/L0单缓冲区</strong></td><td>A、B矩阵在L1和L0中各只有一份缓冲区，下一轮数据必须等上一轮消费完才能搬入</td><td>改为Ping-Pong双缓冲，让数据搬运和计算重叠执行</td></tr><tr><td><strong>MTE2搬运粒度小</strong></td><td>每次DataCopyIn搬入一个baseM×baseK小块，MTE2指令发射密集</td><td>增大搬运粒度，减少MTE2指令次数，提高带宽利用率</td></tr><tr><td><strong>流水线串行执行</strong></td><td>当前实现中使用PipeBarrier和SetFlag/WaitFlag进行流水线同步，但未采用双缓冲机制，MTE2、MTE1、M、FIX各硬件单元无法充分流水并行</td><td>通过双缓冲和硬件事件同步，使四个单元流水并行，显著提升吞吐</td></tr><tr><td><strong>MTE1指令队列压力</strong></td><td>dav-2201下LoadData2D需for循环多次发射，MTE1指令队列深度有限</td><td>使用更高效的Load方式，降低MTE1队列压力</td></tr><tr><td><strong>多核切分固定</strong></td><td>硬编码<code>M / singleCoreM</code>计算核数分配，仅适用于固定矩阵规模和核数场景</td><td>通用切分策略，支撑任意核数和矩阵规模的自动分配</td></tr><tr><td><strong>Tiling参数运行时计算</strong></td><td>核内使用Scalar逐级计算各维度参数，引入额外指令开销</td><td>编译期确定参数，减少运行时开销</td></tr><tr><td><strong>Fixpipe与Cube串行</strong></td><td>L0C 写回必须等Mmad全部完成后才开始，写回期间Cube空闲</td><td>细粒度Fixpipe发射，令写回与计算流水重叠</td></tr><tr><td><strong>B矩阵搬运顺序</strong></td><td>A、B数据依次等量搬运，较大的矩阵场景下B数据到位晚可能成为流水线瓶颈</td><td>优先搬运B矩阵，缓解数据紧张</td></tr><tr><td><strong>L2Cache未充分利用</strong></td><td>当前实现中B矩阵每次均从GM读取，多核反复访问GM导致MTE2带宽压力大；L2Cache纯读带宽约3~4倍于GM，但当前实现未能利用这一特性</td><td>沿M方向切分A矩阵，使B矩阵跨轮驻留L2Cache，减少GM访问次数，有效降低MTE2耗时</td></tr></tbody></table><blockquote><p>以上各优化方向的详细实现方案，请参见<a href="./intermediate_optimization.html">中级性能优化</a>和<a href="./advanced_extreme_optimization.html">高级极限打磨</a>。</p></blockquote></article></div>',1)])])}const g=a(o,[["render",i]]);export{m as __pageData,g as default};
